<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Workboard</title>
    <link rel="stylesheet" href="/styles.css">
    <script type="module" src="/app.js"></script>
  </head>
  <body>
    <main class="container">
      <section id="project-list" aria-labelledby="page-title">
        <h1 id="page-title">Workboard</h1>
        <form id="project-form">
          <label for="project-name">Project name</label>
          <div class="form-row">
            <input id="project-name" name="name" type="text" autocomplete="off">
            <button type="submit">Create project</button>
          </div>
          <p id="form-alert" role="alert" hidden></p>
        </form>
        <div class="project-filter-row">
          <label for="project-filter">Project filter</label>
          <select id="project-filter">
            <option>Active</option>
            <option>Archived</option>
          </select>
        </div>
        <div id="projects" aria-live="polite"></div>
      </section>
      <section id="project-detail" hidden aria-labelledby="project-title">
        <button id="back-button" type="button">Projects</button>
        <h1 id="project-title"></h1>
        <p id="archived-label" hidden>Archived project</p>
        <form id="task-form">
          <label for="task-title">Task title</label>
          <div class="form-row">
            <input id="task-title" name="title" type="text" autocomplete="off">
            <button type="submit">Create task</button>
          </div>
          <p id="task-alert" role="alert" hidden></p>
        </form>
        <div class="task-filter-row">
          <label for="task-filter">Task filter</label>
          <select id="task-filter">
            <option>All</option>
            <option>Open</option>
            <option>Completed</option>
          </select>
        </div>
        <div id="tasks" aria-live="polite"></div>
      </section>
    </main>
  </body>
</html>
:root {
  color: #182230;
  background: #f5f7fa;
  font-family: system-ui, sans-serif;
  font-synthesis: none;
}

body { margin: 0; }
.container { width: min(100% - 2rem, 48rem); margin: 3rem auto; }
h1 { margin: 0 0 1.5rem; font-size: 2rem; }
form { padding: 1.25rem; background: white; border: 1px solid #d8dee8; border-radius: .5rem; }
label { display: block; margin-bottom: .5rem; font-weight: 600; }
.form-row { display: flex; gap: .75rem; }
input { flex: 1; min-width: 0; padding: .65rem .75rem; border: 1px solid #9aa6b2; border-radius: .3rem; font: inherit; }
button { padding: .65rem .9rem; border: 0; border-radius: .3rem; background: #175cd3; color: white; font: inherit; cursor: pointer; }
button:focus-visible, input:focus-visible { outline: 3px solid #84adff; outline-offset: 2px; }
#form-alert { margin: .75rem 0 0; color: #b42318; }
#projects { margin-top: 1.25rem; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem 1.25rem; background: white; border: 1px solid #d8dee8; border-radius: .4rem; }
.project-row + .project-row { margin-top: .5rem; }
#back-button { margin-bottom: 1.25rem; background: #344054; }
.task-filter-row { display: flex; align-items: center; gap: .75rem; margin: 1.25rem 0 .75rem; }
.task-filter-row label { margin: 0; }
select { padding: .55rem .7rem; border: 1px solid #9aa6b2; border-radius: .3rem; font: inherit; background: white; }
.task-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: .85rem 1.25rem; background: white; border: 1px solid #d8dee8; border-radius: .4rem; }
.task-row + .task-row { margin-top: .5rem; }
.task-row label { margin: 0; }
.task-row input { width: 1.1rem; height: 1.1rem; flex: none; }
.project-filter-row { display: flex; align-items: center; gap: .75rem; margin-top: 1.25rem; }
.project-filter-row label { margin: 0; }
button:disabled, input:disabled { opacity: .55; cursor: not-allowed; }
[hidden] { display: none !important; }
